// Explicit child titles must establish identity, not silently
// disappear when supplied in an unsupported structured shape.
if let rawTitle = audio["name"] {
    guard let title = rawTitle as? String,
          AudioSourceFinder.exactMetadataMatch(title: title, creator: wish.artist, wish: wish)
    else { continue }
}

       "contradictory child audio metadata cannot borrow the parent song identity")
for childTitle in [#"["The Song","The Song (Live)"]"#,
                   #"{"@value":"The Song (Live)"}"#, "null"] {
    let malformedChild = structuredPage.replacingOccurrences(
        of: #""@type":"AudioObject","contentUrl""#,
        with: #""@type":"AudioObject","name":"# + childTitle + #","contentUrl""#)
    verify(AutomaticWebAudioFinder.matches(in: malformedChild,
        pageURL: pageURL, wish: wish).isEmpty,
        "explicit unsupported child title cannot inherit parent identity")
}
